def make_weights(n: int, k: int, seed: int, device: torch.device) -> tuple[torch.Tensor, ...]:
    g = torch.Generator(device=device).manual_seed(seed)
    qdata = torch.randint(0, 256, (n, k // 2), dtype=torch.uint8, device=device, generator=g)
    scale = torch.randint(0, 256, (n, k // 32), dtype=torch.uint8, device=device, generator=g)
    zero = torch.randint(0, 256, (n, k // 32), dtype=torch.uint8, device=device, generator=g)
    scale_step = (torch.rand((n, k // 256), device=device, generator=g) * 0.0015 + 0.0005).half()
    zero_step = (torch.rand((n, k // 256), device=device, generator=g) * 0.15 + 0.05).half()
    qdata[0, 0] = 0xF0
    scale[0, 0], scale[0, 1] = 0, 255
    zero[0, 0], zero[0, 1] = 3, 255
    zero_step[0, 0] = torch.tensor(0.1875, device=device, dtype=torch.float16)
    return qdata, scale, scale_step, zero, zero_step


def precision_oracle(x: torch.Tensor, weights: tuple[torch.Tensor, ...], *, chunk_n: int = 256) -> torch.Tensor:
    """FP32 code*FP16-step affine reconstruction, then final BF16 MMA operand."""
    qdata, scale, scale_step, zero, zero_step = weights
    groups = x.shape[1] // 32
    pieces = []
    x_fp32 = x.float()
    for start in range(0, qdata.shape[0], chunk_n):
        end = min(start + chunk_n, qdata.shape[0])
        packed = qdata[start:end]
        q = torch.stack((packed & 15, packed >> 4), dim=-1).float().reshape(end - start, groups, 32)
        scale_group = scale[start:end].float() * scale_step[start:end].float().repeat_interleave(8, 1)
        zero_group = zero[start:end].float() * zero_step[start:end].float().repeat_interleave(8, 1)
        dense_bf16 = ((q - zero_group[..., None]) * scale_group[..., None]).bfloat16()
        pieces.append(torch.nn.functional.linear(x_fp32, dense_bf16.reshape(end - start, -1).float()).bfloat16())
    return torch.cat(pieces, dim=1)


def staged_oracle(x: torch.Tensor, weights: tuple[torch.Tensor, ...], *, chunk_n: int = 256) -> torch.Tensor:
    """Old staged-BF16 diagnostic only; never used as the correctness reference."""
    qdata, scale, scale_step, zero, zero_step = weights
    groups = x.shape[1] // 32
    pieces = []
    for start in range(0, qdata.shape[0], chunk_n):
        end = min(start + chunk_n, qdata.shape[0])
        packed = qdata[start:end]
        q = torch.stack((packed & 15, packed >> 4), dim=-1).float().bfloat16().reshape(end - start, groups, 32)
        sg = (scale[start:end].float().bfloat16() * scale_step[start:end].bfloat16().repeat_interleave(8, 1)).bfloat16()
        zg = (zero[start:end].float().bfloat16() * zero_step[start:end].bfloat16().repeat_interleave(8, 1)).bfloat16()
        dense = ((q - zg[..., None]).bfloat16() * sg[..., None]).bfloat16()
        pieces.append(torch.nn.functional.linear(x.float(), dense.reshape(end - start, -1).float()).bfloat16())
    return torch.cat(pieces, dim=1)


def error_stats(out: torch.Tensor, reference: torch.Tensor) -> dict[str, float]:
    if out.dtype != torch.bfloat16 or out.shape != reference.shape or out.device != reference.device:
        raise AssertionError("candidate output contract mismatch")
    delta = out.float() - reference.float()
    relative_rms = float(delta.square().mean().sqrt() / reference.float().square().mean().sqrt().clamp_min(1e-8))
    if not torch.isfinite(out).all() or relative_rms >= 0.01:
        raise AssertionError(f"finite/RMS gate failed: relative_rms={relative_rms}")
    torch.testing.assert_close(out.float(), reference.float(), rtol=0.05, atol=4.0)
    return {"relative_rms": relative_rms, "max_abs": float(delta.abs().max()), "mean_abs": float(delta.abs().mean())}


def source_hashes() -> dict[str, str]:
    root = Path(__file__).resolve().parent
    names = ("__init__.py", "common.py", "fp32_affine_tiles.py", "validate.py", "README.md")
    return {name: hashlib.sha256((root / name).read_bytes()).hexdigest() for name in names}


def make_activation(kind: str, m: int, k: int, seed: int, device: torch.device) -> torch.Tensor:
    if kind == "zero":
        return torch.zeros((m, k), dtype=torch.bfloat16, device=device)
    if kind == "one":
        return torch.ones((m, k), dtype=torch.bfloat16, device=device)
    g = torch.Generator(device=device).manual_seed(seed + 100_000)
    x = torch.randn((m, k), dtype=torch.bfloat16, device=device, generator=g)
    if m > 1:
        x[0].zero_()
    return x


def config_for(bucket: int) -> dict[str, int]:
    return next(
        dict(cfg) for cfg in fp32_affine_tiles.CONFIGS.values()
        if cfg["bucket"] == bucket and cfg["split_k"] == 1
    )


def run_case(*, bucket: int, m: int, n: int, k: int, activation: str, seed: int,
             config: dict[str, int] | None = None, split_k: int | None = None,
             staged_diagnostic: bool = False) -> dict[str, Any]:
    device = torch.device("cuda")
    x = make_activation(activation, m, k, seed, device)
    weights = make_weights(n, k, seed, device)
    zg = weights[3].float() * weights[4].float().repeat_interleave(8, 1)
    if not bool(((zg - zg.round()).abs() > 0).any()):
        raise AssertionError("fractional zero generation failed")
    reference = precision_oracle(x, weights)
    chosen = dict(config if config is not None else config_for(bucket))
    if split_k is not None:
        chosen["split_k"] = split_k
    started = time.perf_counter()
    out = fp32_affine_tiles.run_diagnostic(x, *weights, bucket=bucket, config=chosen)
    repeated = fp32_affine_tiles.run_diagnostic(x, *weights, bucket=bucket, config=chosen)
    torch.cuda.synchronize()
    stats = error_stats(out, reference)
    if not torch.equal(out, repeated):
        raise AssertionError("candidate output was not deterministic")
    zero_exact = activation != "zero" or bool((out == 0).all())
    if not zero_exact:
        raise AssertionError("zero activation output was not exact zero")
    item = {
        "bucket": bucket, "m": m, "n": n, "k": k, "activation": activation,
        "config": chosen, "split_k": chosen["split_k"], "fractional_zero_points": True,
        "zero_output_exact": zero_exact, "deterministic_repeated_output": True,
        "elapsed_compile_and_run_s": time.perf_counter() - started, **stats,
    }
    if staged_diagnostic:
        staged = staged_oracle(x, weights)
        delta = staged.float() - reference.float()
        staged_rms = float(
            delta.square().mean().sqrt() / reference.float().square().mean().sqrt().clamp_min(1e-8)
        )
        item["old_staged_vs_precision_oracle_relative_rms"] = staged_rms
        if activation == "one" and not staged_rms > stats["relative_rms"]:
            raise AssertionError("all-one fixture does not distinguish FP32 affine from staged BF16")
    return item


def check_ranges() -> dict[str, Any]:
    checks = {}
    for split in common.SUPPORTED_SPLITS:
        ranges = common.balanced_super_ranges(6656, split)
        assert ranges[0][0] == 0 and ranges[-1][1] == 26
        assert all(a < b for a, b in ranges)
        assert all(ranges[i][1] == ranges[i + 1][0] for i in range(len(ranges) - 1))
        checks[str(split)] = ranges
    try:
        common.validate_split(32, 6656)
    except ValueError:
        checks["split32_rejected"] = True
    else:
        raise AssertionError("split32 must be rejected")
    return checks


